19	func (w *Worker) handle(ctx context.Context, m Message) error {
20		var lastErr error
21		for attempt := 0; attempt < 3; attempt++ {
22			if attempt > 0 {
23				time.Sleep(w.backoff(attempt))
24			}
25			if err := w.commitOne(ctx, m); err == nil {
26				return nil
27			} else if errors.Is(err, ErrNotFound) {
28				return nil
29			} else {
30				lastErr = err
31			}
32		}
33		slog.Warn("dropping message after retries", "id", m.ID, "err", lastErr)
34		return nil
35	}

